function extractHost(url) {
  const m = url.match(/^https?:\/\/([^/?#]+)/);
  return m ? m[1].replace(/^www\./, '') : '';
}

const SALON_KEYWORDS = ['美容室', 'ヘアサロン', '美容院', 'サロン', 'hair', 'Hair', 'HAIR'];

function cleanCompanyName(title) {
  if (!title) return title;
  const segments = title.split(/[|–—｜]|-(?=[^-])/)
    .map(s => s.trim())
    .filter(s => s.length > 0);
  if (segments.length <= 1) return title.trim();

  // 最長セグメントが5文字以下なら元のtitleをそのまま返す
  const maxLen = Math.max(...segments.map(s => s.length));
  if (maxLen <= 5) return title.trim();

  // 美容室キーワードを含むセグメントを優先
  const salonSegment = segments.find(s =>
    SALON_KEYWORDS.some(kw => s.includes(kw))
  );
  if (salonSegment) return salonSegment;

  // なければ最も長いセグメントを返す
  return segments.reduce((a, b) => a.length >= b.length ? a : b);
}

return items.map(({ json: item }) => {
  const link = item.link || '';
  let skipItem = !link;
  if (link) {
    const host = extractHost(link);
    skipItem = !host || SKIP_DOMAINS.some(d => host === d || host.endsWith('.' + d));
  }

  return { json: {
    companyName: cleanCompanyName(item.title || ''),
    companyUrl:  link,
    phone:       '',
    address:     '',
    industry:    p.industry,
    area:        p.area,
    spreadsheetId: p.spreadsheetId || '',
    projectId:   p.projectId || '',
    runId:       p.runId || '',
    keyword:     item.keyword || '',
    skipItem,
  }};
});

// L-05: 重複判定 - 全アイテム処理
const items = $input.all();
return items.map(({ json: c }) => ({
  json: { ...c, isDuplicate: false, normalizedHpUrl: c.companyUrl || '', existingFormUrlsArray: [] }
}));

// 全企業URLを1つのリストに集約してscrape APIに渡す
const items = $input.all();
const urlItems = items.map(({ json: c }) => ({
  url: c.companyUrl || '',
  baseUrl: c.companyUrl || '',
})).filter(x => x.url);

const requestBody = JSON.stringify({
  items: urlItems,
  timeoutMs: 8000,
  concurrency: 5,
  fetchFormPage: true,
});

return [{ json: { urlItems, companies: items.map(i => i.json), requestBody } }];

// スクレイプAPI結果を展開
const allInput = $input.all();
if (!allInput.length) return [{ json: { _empty: true } }];

const item = allInput[0].json;
const results = item.results || [];

if (!results.length) return [{ json: { _empty: true } }];

// URL収集ノードから元の企業情報（会社名等）を取得
let companies = [];
try {
  companies = $('URL収集').item.json.companies || [];
} catch(e) {}

// URLをキーにして会社名を引く
const companyMap = {};
for (const c of companies) {
  if (c.companyUrl) companyMap[c.companyUrl] = c;
}

return results.map(r => {
  const origUrl = r.url || r.baseUrl || '';
  const orig = companyMap[origUrl] || {};
  return { json: {
    companyUrl: origUrl,
    companyName: orig.companyName || r.companyName || '',
    keyword: orig.keyword || '',
    formUrl: r.formUrl || null,
    email: r.email || null,
    phone: r.phone || null,
    address: r.address || null,
    hasContactLink: r.hasContactLink || false,
    contactLinks: r.contactLinks || [],
    formPageTitle: r.formPageTitle || '',
    formTypeHint: r.formTypeHint || 'unknown',
    error: r.error || null,
  } };
});

const items = $input.all();
const companies = items.map(i => ({
  name: i.json["会社名"] || "",
  hpUrl: i.json["HP URL"] || "",
  formUrl: i.json["フォームURL"] || "",
  phone: i.json["電話番号"] || "",
  email: i.json["メールアドレス"] || "",
  industry: i.json["業種"] || "",
  area: i.json["エリア"] || "",
  formType: i.json["フォーム種別"] || "",
  status: i.json["ステータス"] || "未送信",
  projectId: i.json["プロジェクトID"] || "",
  runId: i.json["実行ID"] || "",
  collectedAt: i.json["収集日時"] || ""
}));
const runId = items[0]?.json["実行ID"] || "";
return [{ json: { status: "success", companies, runId } }];
